import re
def readable(line):
    if line.startswith('!['):return line
    if line.startswith('-') and not line.startswith('- '):line='- '+line[1:]
    # Keep code identifiers and URLs verbatim; normalize numeric prose spacing.
    pieces=re.split(r'(`[^`]+`|https://[^)\s]+)',line)
    for i,part in enumerate(pieces):
        if part.startswith(('`','https://')):continue
        part=re.sub(r'(?<=[A-Za-z])(?=[0-9])',' ',part)
        part=re.sub(r'(?<=[0-9])(?=[A-Za-z])',' ',part)
        part=re.sub(r'(?<=[,;:])(?=[A-Za-z$+0-9])',' ',part)
        part=re.sub(r'\bz ([0-9])',r'z\1',part)
        part=re.sub(r'\blog ([0-9])',r'log\1',part)
        part=re.sub(r'([0-9]) (st|nd|rd|th)\b',r'\1\2',part)
        part=re.sub(r'(?<=[A-Za-z])(?=\$|\+\$|−\$)',' ',part)
        part=re.sub(r'(?<=[0-9]) (?=[WL])','',part)
        pieces[i]=part
    return ''.join(pieces)
